def E(code, name, kind, pattern, primary, secondary, role, muscles, equipment,
      environments, level, costs, supervision, dose, instructions, cues, mistakes,
      safety, progressions, regressions, substitutions, aliases=""):
    method_type = {
        "landing_drill": "athletic_drill",
        "speed_drill": "athletic_drill",
        "deceleration_drill": "athletic_drill",
        "change_of_direction_drill": "athletic_drill",
        "reactive_agility_drill": "athletic_drill",
        "isometric": "exercise",
        "recovery_modality": "conditioning_modality",
    }.get(kind, kind)
    return dict(code=code, exercise_name=name, aliases=aliases, type=method_type,
                movement_pattern=pattern, primary_quality=primary,
                secondary_qualities=secondary, training_role=role,
                primary_muscles=muscles, secondary_muscles="trunk;supporting musculature",
                equipment=equipment, environments=environments, minimum_level=level,
                technical_cost=str(costs[0]), impact_cost=str(costs[1]),
                fatigue_cost=str(costs[2]), supervision_required=supervision,
                dose_units=dose, instructions=instructions, coaching_cues=cues,
                common_mistakes=mistakes, safety_stop_conditions=safety,
                progressions=progressions, regressions=regressions,
                substitutions=substitutions)


