def modality(code, name, pattern, quality, secondary, equipment, env, level, costs,
             instructions, cues, mistakes, safety, progressions, regressions, substitutions):
    return E(code, name, "conditioning_modality", pattern, quality, secondary, "primary",
             "cardiorespiratory_system;whole_body", equipment, env, level, costs, "no",
             COND_DOSE, instructions, cues, mistakes, safety, progressions, regressions,
             substitutions)


