def main():
    with CSV_PATH.open(encoding="utf-8-sig", newline="") as fh:
        existing = list(csv.DictReader(fh))
    existing = [row for row in existing if not row["source_id"].startswith("EXT-")]
    existing_codes = {row["code"] for row in existing}
    new_codes = [row["code"] for row in ENTRIES]
    if len(ENTRIES) != 58 or len(new_codes) != len(set(new_codes)):
        raise SystemExit(f"Expected 58 unique entries, found {len(ENTRIES)} rows/{len(set(new_codes))} codes")
    overlap = existing_codes & set(new_codes)
    if overlap:
        raise SystemExit(f"Extension codes already exist: {sorted(overlap)}")
    output = existing[:]
    for index, item in enumerate(ENTRIES, 1):
        row = {field: "" for field in FIELDS}
        row.update(item)
        row.update({
            "source_id": f"EXT-{index:03d}",
            "catalogue_scope": "template_required_extension",
            "generator_eligible": "no",
            "approval_status": "pending_review",
            "approved_by": "",
            "approval_scope": "Research-derived candidate; requires content, safety and taxonomy review before generator release",
        })
        output.append(row)
    with CSV_PATH.open("w", encoding="utf-8", newline="") as fh:
        writer = csv.DictWriter(fh, fieldnames=FIELDS, extrasaction="raise")
        writer.writeheader()
        writer.writerows(output)
    print(f"Wrote {len(output)} rows: {len(existing)} existing + {len(ENTRIES)} extensions")


if __name__ == "__main__":
    main()
